use mdbook_language_lab::process;
use serde_json::{Value, json};

fn chapter(path: &str, content: &str) -> Value {
    json!({"Chapter": {"path": path, "content": content, "sub_items": []}})
}
fn render(source: &str) -> String {
    let mut book = json!({"items": [chapter("test.md", source)]});
    process(&mut book).unwrap();
    book["items"][0]["Chapter"]["content"]
        .as_str()
        .unwrap()
        .into()
}

chapters(items, &mut |ch| {
    let source = ch["content"].as_str().ok_or("missing chapter content")?;
    let mut output = source.to_owned();
    for role in roles(source).into_iter().rev() {
        let path = ch["path"]
            .as_str()
            .ok_or("role in chapter without output path")?;
        let definition = role.name == "req";
        let id = if definition { &role.label } else { &role.name };
        let target = definitions
            .get(id)
            .ok_or_else(|| format!("{path}: unknown requirement {id}"))?;
        let html = if definition {
            format!(
                "<a class=\"requirement-badge\" id=\"req-{id}\" href=\"#req-{id}\" aria-label=\"Requirement {id}\"><span class=\"requirement-kind\">REQ</span><span class=\"requirement-name\">{id}</span></a>"
            )
        } else {
            format!(
                "<a class=\"requirement-reference\" href=\"{}\" title=\"Requirement {id}\">{}</a>",
                escape(&href(path, target, id)),
                escape(&role.label)
            )
        };
        output.replace_range(role.range, &html);
    }
    ch["content"] = output.into();
    Ok(())

#[test]
fn badges_are_visible_accessible_and_offline_with_focus_styles() {
    let output = render("{req}`record.identity` Text.\n\n{record.identity}`identity`");
    assert!(output.contains("id=\"req-record.identity\" href=\"#req-record.identity\" aria-label=\"Requirement record.identity\""));
    assert!(output.contains("<span class=\"requirement-kind\">REQ</span>"));
    assert!(output.contains("<span class=\"requirement-name\">record.identity</span>"));
    for forbidden in ["<script", "<img", "src=", "http:", "https:", "onclick="] {
        assert!(!output.contains(forbidden));
    }
    let css = include_str!("../../theme/requirements.css");
    assert!(!css.contains("url("));
    assert!(!css.contains("@import"));
    assert!(css.contains(".requirement-badge:focus-visible, .requirement-reference:focus-visible { outline: 3px solid #d97706; outline-offset: 3px; }"));
    assert!(!css.contains("display: none"));
    assert!(!css.contains("visibility: hidden"));
    let config = include_str!("../../book.toml");
    assert!(config.contains("additional-css = [\"theme/requirements.css\"]"));
}

.requirement-badge {
    display: inline-flex;
    align-items: stretch;
    border-radius: 5px;
    overflow: hidden;
    vertical-align: middle;
    font: 600 0.76em/1.7 ui-monospace, SFMono-Regular, Consolas, monospace;
    box-shadow: 0 1px 3px #0003;
    text-decoration: none !important;
    margin: 0 .35em .15em 0;
    scroll-margin-top: 5rem;
}
.requirement-kind { background: #334155; color: #fff; padding: .08em .6em; letter-spacing: .05em; }
.requirement-name { background: #087e8b; color: #fff; padding: .08em .65em; }
.requirement-badge:hover .requirement-name { background: #09616b; }
.requirement-badge:target { outline: 3px solid #d97706; outline-offset: 3px; }
.requirement-badge:focus-visible, .requirement-reference:focus-visible { outline: 3px solid #d97706; outline-offset: 3px; }
.requirement-reference { text-decoration: underline; text-underline-offset: .18em; }
@media print { .requirement-badge { box-shadow: none; border: 1px solid #64748b; } }
